WITH history_types AS (
  SELECT DISTINCT PostHistoryTypeId FROM postHistory WHERE PostId = 3720
),
commenters AS (
  SELECT COUNT(DISTINCT UserId) AS UniqueCommenters FROM comments WHERE PostId = 3720
)
SELECT ht.PostHistoryTypeId, c.UniqueCommenters
FROM history_types ht
CROSS JOIN commenters c;

WITH teacher AS (
  SELECT COUNT(DISTINCT UserId) AS cnt FROM badges WHERE Name = 'Teacher'
),
total AS (
  SELECT COUNT(DISTINCT UserId) AS cnt FROM badges
)
SELECT CAST(teacher.cnt AS REAL) / total.cnt * 100 AS percentage
FROM teacher, total;

SELECT Tags
FROM posts
WHERE OwnerUserId = (SELECT Id FROM users WHERE DisplayName = 'John Salvatier');

SELECT COUNT(*)
FROM comments
WHERE PostId = (SELECT Id FROM posts WHERE Score = (SELECT MAX(Score) FROM posts));

SELECT
  (SELECT COUNT(*) FROM comments WHERE PostId = (SELECT Id FROM posts WHERE Title = 'Clustering 1D data')) AS num_comments,
  (SELECT COUNT(*) FROM posts WHERE ParentId = (SELECT Id FROM posts WHERE Title = 'Clustering 1D data')) AS num_answers;

WITH total_kam AS (
  SELECT COUNT(*) AS cnt FROM customers WHERE Segment = 'KAM'
),
kam_euro AS (
  SELECT COUNT(*) AS cnt FROM customers WHERE Segment = 'KAM' AND Currency = 'EUR'
)
SELECT kam_euro.cnt * 100.0 / total_kam.cnt AS percentage
FROM kam_euro, total_kam;

SELECT SUM(CASE WHEN type = 'Community Service' THEN 1 ELSE 0 END) * 100.0 / COUNT(event_id) AS percentage
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT SUM(CASE WHEN gender_id = 2 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage_female
FROM superhero
WHERE alignment_id = 2;

WITH brown_colour AS (
    SELECT id FROM colour WHERE colour = 'brown'
),
light_heroes AS (
    SELECT id, superhero_name, full_name FROM superhero WHERE weight_kg < 100
)
SELECT lh.full_name
FROM light_heroes lh
JOIN superhero s ON s.id = lh.id
JOIN brown_colour bc ON s.eye_colour_id = bc.id;

SELECT MAX(STRFTIME('%Y', Birthday)) - MIN(STRFTIME('%Y', Birthday)) AS age_gap
FROM Patient
WHERE ID IN (SELECT DISTINCT ID FROM Laboratory WHERE TG >= 200);

SELECT
  (SELECT COUNT(*) FROM bond WHERE molecule_id = 'TR006' AND bond_type = ' = ') AS double_bond_count,
  (SELECT label FROM molecule WHERE molecule_id = 'TR006') AS is_carcinogenic;

WITH m1 AS (
  SELECT molecule_id FROM atom WHERE atom_id = 'TR000_2'
),
m2 AS (
  SELECT molecule_id FROM atom WHERE atom_id = 'TR000_4'
)
SELECT molecule.molecule_id, molecule.label
FROM molecule
WHERE molecule.molecule_id = (SELECT molecule_id FROM m1)
  AND molecule.molecule_id = (SELECT molecule_id FROM m2);

SELECT COUNT(*) 
FROM comments 
WHERE PostId IN (SELECT Id FROM posts WHERE ViewCount = 1910);

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT COUNT(*) 
FROM comments 
WHERE PostId = (SELECT Id FROM posts ORDER BY Score DESC LIMIT 1);

SELECT SUM(type = 'Community Service') * 100.0 / COUNT(event_id) AS percentage_share
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT COUNT(CASE WHEN Admission = '+' THEN 1 END) * 100.0 / COUNT(*) 
FROM Patient 
WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31';

SELECT MAX(CAST(SUBSTR(Birthday, 1, 4) AS INTEGER)) - MIN(CAST(SUBSTR(Birthday, 1, 4) AS INTEGER)) AS age_gap
FROM Patient
WHERE ID IN (SELECT ID FROM Laboratory WHERE TG >= 200);

SELECT CAST(SUM(CASE WHEN p.SEX = 'M' AND l.UA <= 8.0 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN p.SEX = 'F' AND l.UA <= 6.5 THEN 1 ELSE 0 END) AS ratio
FROM Patient p
JOIN Laboratory l ON p.ID = l.ID;

SELECT CAST(SUM(SEX = 'F') AS REAL) * 100 / COUNT(SEX) AS percentage
FROM Patient
WHERE strftime('%Y', Birthday) = '1980' AND Diagnosis = 'RA';

SELECT SUM(atom.element = 'c') * 100.0 / COUNT(atom.atom_id) AS percentage
FROM atom
WHERE atom.molecule_id IN (SELECT DISTINCT molecule_id FROM bond WHERE bond_type = '=');

SELECT SUM(CASE WHEN bond_type = ' = ' THEN 1 ELSE 0 END) * 100.0 / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT CASE WHEN label = '+' THEN 'yes' ELSE 'no' END AS is_carcinogenic
FROM molecule
WHERE molecule_id = 'TR151';

SELECT
  (SELECT COUNT(*) FROM comments WHERE PostId = (SELECT Id FROM posts WHERE Title = 'Clustering 1D data')) AS CommentCount,
  (SELECT COUNT(*) FROM posts WHERE ParentId = (SELECT Id FROM posts WHERE Title = 'Clustering 1D data') AND PostTypeId = 2) AS AnswerCount;

SELECT CAST(SUM(CASE WHEN Score > 50 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(Id) AS percentage
FROM posts
WHERE OwnerUserId = (SELECT Id FROM users ORDER BY Reputation DESC LIMIT 1);

SELECT CAST(SUM(CASE WHEN major_name = 'Finance' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN major_name = 'Physics' THEN 1 ELSE 0 END) AS ratio
FROM major
JOIN member ON member.link_to_major = major.major_id;

SELECT MAX(CAST(strftime('%Y', Birthday) AS INTEGER)) - MIN(CAST(strftime('%Y', Birthday) AS INTEGER)) AS age_gap
FROM Patient
WHERE ID IN (SELECT DISTINCT ID FROM Laboratory WHERE TG >= 200);

SELECT SUM(CASE WHEN p.SEX = 'M' AND l.UA <= '8.0' THEN 1 ELSE 0 END) * 1.0 / SUM(CASE WHEN p.SEX = 'F' AND l.UA <= '6.5' THEN 1 ELSE 0 END) AS male_to_female_ratio
FROM Patient p
JOIN Laboratory l ON p.ID = l.ID;

SELECT DisplayName, Age
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT COUNT(*) 
FROM posts 
WHERE ViewCount > (SELECT AVG(ViewCount) FROM posts);

SELECT A3 AS branch_location, A2 AS district_name
FROM district
WHERE A13 = (SELECT MAX(A13) FROM district);

SELECT CAST(SUM(m.major_name = 'Finance') AS REAL) / SUM(m.major_name = 'Physics') AS ratio
FROM major m
JOIN member mem ON m.major_id = mem.link_to_major;

SELECT SUM(CASE WHEN superhero.gender_id = 2 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM superhero
WHERE superhero.alignment_id = 2;

SELECT ID, SEX, Diagnosis
FROM Patient
WHERE ID IN (SELECT ID FROM Laboratory WHERE ALB < 3.5);

SELECT MAX(CAST(strftime('%Y', Birthday) AS INTEGER)) - MIN(CAST(strftime('%Y', Birthday) AS INTEGER))
FROM Patient
WHERE ID IN (SELECT ID FROM Laboratory WHERE TG >= 200);

SELECT SUM(CASE WHEN atom.element = 'c' THEN 1 ELSE 0 END) * 100.0 / COUNT(atom.atom_id)
FROM atom
WHERE atom.molecule_id IN (SELECT DISTINCT molecule_id FROM bond WHERE bond_type = '=');

SELECT CAST(SUM(bond_type = ' = ') AS REAL) * 100 / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT
  (SELECT COUNT(*) FROM comments c JOIN posts p ON c.PostId = p.Id WHERE p.Title = 'Clustering 1D data') AS comment_count,
  (SELECT COUNT(*) FROM posts a JOIN posts p ON a.ParentId = p.Id WHERE p.Title = 'Clustering 1D data') AS answer_count;

SELECT 100.0 * SUM(CASE WHEN p.Score > 50 THEN 1 ELSE 0 END) / COUNT(p.Id) AS percentage
FROM posts p
WHERE p.OwnerUserId = (SELECT Id FROM users ORDER BY Reputation DESC LIMIT 1);

SELECT 100.0 * COUNT(DISTINCT CASE WHEN b.Name = 'Teacher' THEN b.UserId END) / COUNT(DISTINCT b.UserId) AS Percentage
FROM badges b
JOIN users u ON u.Id = b.UserId;

SELECT Reputation, Views
FROM users
WHERE DisplayName = 'Jarrod Dixon';

SELECT SUM(CASE WHEN c.Currency = 'Euro' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM customers c
WHERE c.Segment = 'KAM';

SELECT 100.0 * COUNT(DISTINCT CASE WHEN PA.strength > 80 AND PA.stamina > 80 THEN P.player_api_id END) / COUNT(DISTINCT P.player_api_id) AS percentage
FROM Player P
JOIN Player_Attributes PA ON P.player_api_id = PA.player_api_id;

SELECT SUM(major.major_name = 'Finance') * 1.0 / SUM(major.major_name = 'Physics') AS ratio
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';

SELECT SUM(type = 'Community Service') * 100.0 / COUNT(event_id) AS percentage_share
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT SUM(s1.weight_kg) - SUM(s2.weight_kg) AS difference
FROM superhero AS s1
JOIN superhero AS s2 ON s1.full_name = 'Emil Blonsky' AND s2.full_name = 'Charles Chandler';

SELECT s.full_name
FROM superhero s
WHERE s.weight_kg = 0 OR s.weight_kg IS NULL;

SELECT s.full_name
FROM superhero s
WHERE s.superhero_name = 'Alien';

SELECT CAST(SUM(CASE WHEN p.SEX = 'M' AND l.UA <= '8.0' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN p.SEX = 'F' AND l.UA <= '6.5' THEN 1 ELSE 0 END) AS male_to_female_ratio
FROM Laboratory l
JOIN Patient p ON l.ID = p.ID;
